import { useState } from "react";
import { useNavigate } from "react-router-dom";
import { 
  Search, 
  MapPin, 
  Scale, 
  Star, 
  Briefcase, 
  Clock,
  Filter,
  ChevronRight,
  Phone,
  Mail,
  Globe,
  Award,
  BookOpen,
  ThumbsUp
} from "lucide-react";

export default function Lawyers() {
  const navigate = useNavigate();
  const [searchTerm, setSearchTerm] = useState("");
  const [selectedCity, setSelectedCity] = useState("");
  const [selectedSpecialty, setSelectedSpecialty] = useState("");
  const [showFilters, setShowFilters] = useState(false);

  // TODO: Replace with actual data from your database
  const lawyers = []; // This will be populated from your backend
  const cities = []; // This will be populated from your backend
  const specialties = []; // This will be populated from your backend

  // TODO: Implement filter logic based on actual data structure
  const filteredLawyers = lawyers; // This will be replaced with actual filtering

  return (
    <div className="min-h-screen bg-[#F8F7F2]">
      {/* Header */}
      <div className="bg-white shadow-sm border-b border-gray-200">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-4">
          <div className="flex justify-between items-center">
            <button
              onClick={() => navigate("/dashboard")}
              className="flex items-center gap-2 text-[#1A2035] hover:text-[#D4AF37] transition"
            >
              <ChevronRight size={20} className="rotate-180" />
              <span className="font-medium">Back to Dashboard</span>
            </button>
            <h1 className="text-2xl font-bold text-[#1A2035]">Find a Lawyer</h1>
            <div className="w-24"></div> {/* Spacer */}
          </div>
        </div>
      </div>

      {/* Hero Section */}
      <div className="bg-[#1A2035] text-white">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-12">
          <div className="flex items-center gap-4 mb-6">
            <Scale size={48} className="text-[#D4AF37]" />
            <h2 className="text-4xl font-bold">Connect with Expert Lawyers</h2>
          </div>
          <p className="text-xl text-gray-300 max-w-3xl">
            Find trusted legal professionals in your city. Filter by specialty, experience, 
            and ratings to find the perfect match for your legal needs.
          </p>
        </div>
      </div>

      {/* Search and Filters */}
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <div className="bg-white rounded-2xl shadow-lg p-6 mb-8">
          <div className="flex flex-col md:flex-row gap-4">
            {/* Search Bar */}
            <div className="flex-1 relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={20} />
              <input
                type="text"
                placeholder="Search by name, specialty, or firm..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full pl-10 pr-4 py-3 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-[#D4AF37] focus:border-transparent"
              />
            </div>

            {/* Filter Toggle Button (Mobile) */}
            <button
              onClick={() => setShowFilters(!showFilters)}
              className="md:hidden flex items-center justify-center gap-2 px-4 py-3 bg-[#1A2035] text-white rounded-xl"
            >
              <Filter size={20} />
              Filters
            </button>

            {/* Desktop Filters */}
            <div className="hidden md:flex gap-4">
              <select
                value={selectedCity}
                onChange={(e) => setSelectedCity(e.target.value)}
                className="px-4 py-3 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-[#D4AF37] bg-white"
              >
                <option value="">All Cities</option>
                {/* TODO: Map through cities from database */}
                {cities.map((city, index) => (
                  <option key={index} value={city}>{city}</option>
                ))}
              </select>

              <select
                value={selectedSpecialty}
                onChange={(e) => setSelectedSpecialty(e.target.value)}
                className="px-4 py-3 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-[#D4AF37] bg-white"
              >
                <option value="">All Specialties</option>
                {/* TODO: Map through specialties from database */}
                {specialties.map((specialty, index) => (
                  <option key={index} value={specialty}>{specialty}</option>
                ))}
              </select>
            </div>
          </div>

          {/* Mobile Filters */}
          {showFilters && (
            <div className="mt-4 md:hidden space-y-4">
              <select
                value={selectedCity}
                onChange={(e) => setSelectedCity(e.target.value)}
                className="w-full px-4 py-3 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-[#D4AF37] bg-white"
              >
                <option value="">All Cities</option>
                {/* TODO: Map through cities from database */}
                {cities.map((city, index) => (
                  <option key={index} value={city}>{city}</option>
                ))}
              </select>

              <select
                value={selectedSpecialty}
                onChange={(e) => setSelectedSpecialty(e.target.value)}
                className="w-full px-4 py-3 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-[#D4AF37] bg-white"
              >
                <option value="">All Specialties</option>
                {/* TODO: Map through specialties from database */}
                {specialties.map((specialty, index) => (
                  <option key={index} value={specialty}>{specialty}</option>
                ))}
              </select>
            </div>
          )}

          {/* Results count */}
          <div className="mt-4 text-sm text-gray-600">
            Found <span className="font-bold text-[#1A2035]">{filteredLawyers.length}</span> lawyers matching your criteria
          </div>
        </div>

        {/* Lawyers Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {/* TODO: Map through filteredLawyers from database */}
          {filteredLawyers.map((lawyer, index) => (
            <div
              key={lawyer.id || index}
              className="bg-white rounded-2xl shadow-lg overflow-hidden hover:shadow-xl transition transform hover:-translate-y-1"
            >
              {/* Profile Header */}
              <div className="relative h-32 bg-gradient-to-r from-[#1A2035] to-[#303658]">
                <div className="absolute -bottom-12 left-6">
                  <img
                    src={lawyer.image}
                    alt={lawyer.name}
                    className="w-24 h-24 rounded-xl border-4 border-white shadow-lg object-cover"
                  />
                </div>
              </div>

              {/* Badges */}
              <div className="absolute top-4 right-4 flex gap-2">
                {/* TODO: Map through lawyer.badges */}
                {lawyer.badges?.map((badge, index) => (
                  <span
                    key={index}
                    className="px-2 py-1 bg-[#D4AF37] text-[#1A2035] text-xs font-bold rounded-full"
                  >
                    {badge}
                  </span>
                ))}
              </div>

              {/* Content */}
              <div className="pt-14 p-6">
                <h3 className="text-xl font-bold text-[#1A2035] mb-1">{lawyer.name}</h3>
                <p className="text-[#D4AF37] font-medium mb-2">{lawyer.firm}</p>

                {/* Rating */}
                <div className="flex items-center gap-2 mb-3">
                  <div className="flex items-center">
                    <Star size={16} className="text-[#D4AF37] fill-current" />
                    <span className="ml-1 font-bold">{lawyer.rating}</span>
                  </div>
                  <span className="text-sm text-gray-500">({lawyer.reviews} reviews)</span>
                </div>

                {/* Details */}
                <div className="space-y-2 mb-4">
                  <div className="flex items-center gap-2 text-gray-600">
                    <Briefcase size={16} className="text-[#D4AF37]" />
                    <span className="text-sm">{lawyer.specialty}</span>
                  </div>
                  <div className="flex items-center gap-2 text-gray-600">
                    <MapPin size={16} className="text-[#D4AF37]" />
                    <span className="text-sm">{lawyer.city}</span>
                  </div>
                  <div className="flex items-center gap-2 text-gray-600">
                    <Clock size={16} className="text-[#D4AF37]" />
                    <span className="text-sm">{lawyer.experience} experience</span>
                  </div>
                  <div className="flex items-center gap-2 text-gray-600">
                    <Award size={16} className="text-[#D4AF37]" />
                    <span className="text-sm">{lawyer.education}</span>
                  </div>
                </div>

                {/* Languages */}
                <div className="mb-4">
                  <div className="flex flex-wrap gap-1">
                    {/* TODO: Map through lawyer.languages */}
                    {lawyer.languages?.map((lang, index) => (
                      <span
                        key={index}
                        className="px-2 py-1 bg-gray-100 text-gray-600 text-xs rounded-full"
                      >
                        {lang}
                      </span>
                    ))}
                  </div>
                </div>

                {/* Availability */}
                <div className="mb-4">
                  <span className="text-sm text-green-600 font-medium flex items-center gap-1">
                    <ThumbsUp size={14} />
                    {lawyer.availability}
                  </span>
                </div>

                {/* Rate and Contact */}
                <div className="flex items-center justify-between pt-4 border-t border-gray-100">
                  <div>
                    <span className="text-sm text-gray-500">Hourly Rate</span>
                    <p className="text-xl font-bold text-[#1A2035]">{lawyer.hourlyRate}</p>
                  </div>
                  <div className="flex gap-2">
                    <button
                      onClick={() => window.location.href = `tel:${lawyer.phone}`}
                      className="p-2 bg-gray-100 rounded-lg hover:bg-[#D4AF37] hover:text-white transition"
                      title="Call"
                    >
                      <Phone size={18} />
                    </button>
                    <button
                      onClick={() => window.location.href = `mailto:${lawyer.email}`}
                      className="p-2 bg-gray-100 rounded-lg hover:bg-[#D4AF37] hover:text-white transition"
                      title="Email"
                    >
                      <Mail size={18} />
                    </button>
                    <button
                      onClick={() => window.open(lawyer.website, '_blank')}
                      className="p-2 bg-gray-100 rounded-lg hover:bg-[#D4AF37] hover:text-white transition"
                      title="Website"
                    >
                      <Globe size={18} />
                    </button>
                  </div>
                </div>

                {/* View Profile Button */}
                <button
                  onClick={() => navigate(`/lawyer/${lawyer.id}`)}
                  className="w-full mt-4 py-2 bg-[#1A2035] text-white rounded-xl font-medium hover:bg-[#303658] transition flex items-center justify-center gap-2"
                >
                  <BookOpen size={16} />
                  View Full Profile
                </button>
              </div>
            </div>
          ))}
        </div>

        {/* No Results */}
        {filteredLawyers.length === 0 && (
          <div className="text-center py-12">
            <div className="bg-white rounded-2xl p-12 shadow-lg">
              <Scale size={48} className="mx-auto text-[#D4AF37] mb-4" />
              <h3 className="text-2xl font-bold text-[#1A2035] mb-2">No Lawyers Found</h3>
              <p className="text-gray-600 mb-6">
                Try adjusting your search criteria or filters to find more lawyers.
              </p>
              <button
                onClick={() => {
                  setSearchTerm("");
                  setSelectedCity("");
                  setSelectedSpecialty("");
                }}
                className="px-6 py-3 bg-[#D4AF37] text-[#1A2035] rounded-xl font-medium hover:bg-[#B85C38] hover:text-white transition"
              >
                Clear All Filters
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
